The idea is to keep the strong maintenance-staggering bias from the original rule (prefer robots with the least remaining work budget) while adding a small penalty for high duty hours to improve balance. For new robots, we refine the type preference by scoring each type's overhead (travel + charge) per duty hour and its maintenance burden, then prefer types that fit the remaining horizon, have larger duty lengths, and better efficiency.

```python
def rule(ctx):
    actions = []
    avail = ctx.available
    if avail:
        # Prefer lower remaining budget (more urgent for maintenance staggering),
        # but lightly penalize high duty hours to balance the roster.
        def reuse_key(r):
            return (r.budget + 0.15 * r.hours, r.count, r.idx)
        actions = [("reuse", r) for r in sorted(avail, key=reuse_key)]

    # New robot type preferences
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)
    if not valid:
        return actions

    def new_key(k):
        t = ctx.types[k]
        wt = t['work_time']
        overhead = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        # Lower score = better: less overhead per duty hour, less maintenance burden.
        score = overhead / wt + t['maintenance_time'] / t['continue_max_work']
        if wt <= ctx.remaining:
            # Fitting types: prefer larger work_time, then better efficiency.
            return (0, -wt, score, k)
        else:
            # Non-fitting: prefer smaller work_time, then better efficiency.
            return (1, wt, score, k)

    valid.sort(key=new_key)
    if ctx.gene_type in valid:
        valid.remove(ctx.gene_type)
        valid.insert(0, ctx.gene_type)

    actions.extend(("new", k) for k in valid)
    return actions
```

The rule uses a maintenance-aware balance metric: it prefers available robots that have not yet hit their first maintenance and have used the smallest fraction of their maintenance budget, which directly targets the first-maintenance-time imbalance while still balancing duty hours and counts. It also proactively opens a new robot when the estimated remaining capacity is less than the remaining horizon, choosing a type that maximizes work before maintenance, so new resources are introduced early to absorb work and avoid last-minute repairs.

```python
def rule(ctx):
    # Lower utilization = less of the maintenance budget used so far.
    def utilization(r):
        t = ctx.types[r.type]
        if t is None or t['continue_max_work'] <= 0:
            return 0.0
        return (t['continue_max_work'] - r.budget) / t['continue_max_work']

    # Prefer robots without a first maintenance yet, then lowest utilization,
    # then fewest duties, then earliest ready time.
    ordered = sorted(
        ctx.available,
        key=lambda r: (r.first_maint is not None, utilization(r), r.count, r.ready)
    )
    actions = [("reuse", r) for r in ordered]

    # If existing capacity cannot cover the remaining horizon, open a new robot proactively.
    need_new = False
    try:
        need_new = ctx.capacity < ctx.remaining
    except Exception:
        need_new = False

    if need_new:
        best_k = None
        # Prefer the genome's type if it is still allowed and fits in the remaining time.
        if ctx.left[ctx.gene_type] > 0:
            t = ctx.types[ctx.gene_type]
            if t is not None and t['work_time'] <= ctx.remaining:
                best_k = ctx.gene_type

        if best_k is None:
            best_score = -1.0
            for k in range(len(ctx.types)):
                if ctx.left[k] > 0 and ctx.types[k] is not None:
                    t = ctx.types[k]
                    if t['work_time'] <= ctx.remaining:
                        # Total duty hours this robot can supply before maintenance.
                        duties = t['continue_max_work'] / max(1, t['single_work_time'])
                        score = duties * t['work_time']
                        if score > best_score:
                            best_score = score
                            best_k = k

        if best_k is None:
            for k in range(len(ctx.types)):
                if ctx.left[k] > 0:
                    best_k = k
                    break

        if best_k is not None:
            actions.insert(0, ("new", best_k))

    # Always keep a new-robot option at the end for deviation slots / fallback.
    if ctx.left[ctx.gene_type] > 0:
        if not (actions and actions[0][0] == "new" and actions[0][1] == ctx.gene_type):
            actions.append(("new", ctx.gene_type))
    else:
        for k in range(len(ctx.types)):
            if ctx.left[k] > 0:
                actions.append(("new", k))
                break

    return actions
```

