The combined rule uses Rule 1's maintenance-urgency ordering (fewer duties left, then robots without first maintenance) as the primary reuse key, but inserts Rule 2's balanced tie-breaker (`budget + 0.15 * hours`) so that equally urgent robots are chosen with some workload smoothing. For opening new robots, it merges Rule 1's capacity preference with Rule 2's work‑time and efficiency logic into a single lexicographic key: fitting types are ranked by larger capacity, then larger work time, then lower overhead/maintenance burden; non‑fitting types are ranked by smaller work time, then efficiency, then capacity. The genome's preferred type is still given top priority when valid.

```python
def rule(ctx):
    actions = []
    # Reuse: urgency (fewer duties left before maintenance) first,
    # then robots that haven't had first maintenance,
    # then balance via budget + 0.15 * hours, then count, then idx.
    if ctx.available:
        def reuse_key(r):
            return (r.duties_left, r.first_maint is not None,
                    r.budget + 0.15 * r.hours, r.count, r.idx)
        actions = [("reuse", r) for r in sorted(ctx.available, key=reuse_key)]

    # New robot type preferences
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)
    if not valid:
        return actions

    def new_key(k):
        t = ctx.types[k]
        wt = t['work_time']
        fits = 0 if wt <= ctx.remaining else 1
        cap = (t['continue_max_work'] // t['single_work_time']) * wt
        overhead = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        # Efficiency: overhead per duty hour + maintenance burden per duty hour
        if cap > 0:
            efficiency = overhead / wt + t['maintenance_time'] / cap
        else:
            efficiency = 1e9
        if fits == 0:
            # Fitting: prefer larger capacity, then larger work_time, then efficiency
            return (fits, -cap, -wt, efficiency, k)
        else:
            # Non-fitting: prefer smaller work_time, then efficiency, then larger capacity
            return (fits, wt, efficiency, -cap, k)

    valid.sort(key=new_key)
    # Give genome's preferred type priority if valid
    if ctx.gene_type in valid:
        valid.remove(ctx.gene_type)
        valid.insert(0, ctx.gene_type)

    actions.extend(("new", k) for k in valid)
    return actions
```

The key improvement is a dynamic threshold that switches between balancing and draining based on the robot's maintenance cycle. Early in a cycle, we balance duty counts and hours across robots; once a robot gets close to maintenance (within the number of duties needed to cover the maintenance downtime), we switch to draining the most urgent robot first. This staggers maintenance starts just enough to avoid overlap while keeping counts as even as possible. We also add an endgame cover priority to finish the horizon in one shift when possible, and include cycle time in the new-robot preference.

```python
def rule(ctx):
    # Compute max work_time for endgame cover
    max_wt = 0
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None:
            wt = t['work_time']
            if wt > max_wt:
                max_wt = wt

    def reuse_key(r):
        t = ctx.types[r.type]
        # Endgame: prioritize covering remaining horizon
        if ctx.remaining <= max_wt:
            wt = t['work_time']
            if wt >= ctx.remaining:
                # can cover in one shift; prefer smallest wt that covers
                return (0, wt, r.duties_left, r.count, r.hours, r.first_maint is not None, r.idx)
            else:
                # cannot cover; just use urgency/balance
                return (1, r.duties_left, r.count, r.hours, r.first_maint is not None, r.idx)

        # Normal: dynamic threshold between balance and drain
        C = t['continue_max_work'] / max(1, t['single_work_time'])
        thresh = t['maintenance_time'] / max(1, t['work_time'])
        thresh = max(1, min(C, thresh))

        if r.duties_left <= thresh:
            # drain mode: most urgent first
            return (0, r.duties_left, r.count, r.hours, r.first_maint is not None, r.idx)
        else:
            # balance mode: fewer counts first, then fewer hours, then more urgent
            return (1, r.count, r.hours, r.duties_left, r.first_maint is not None, r.idx)

    actions = [("reuse", r) for r in sorted(ctx.available, key=reuse_key)]

    # New robot types: prefer those that fit, then shorter maintenance, then shorter cycle
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)
    if not valid:
        return actions

    def new_key(k):
        t = ctx.types[k]
        wt = t['work_time']
        fits = 0 if wt <= ctx.remaining else 1
        wt_pref = -wt if fits == 0 else wt
        cycle = t['out_travel_time'] + t['work_time'] + t['return_travel_time'] + t['charge_time']
        return (fits, wt_pref, t['maintenance_time'], cycle, -t['continue_max_work'], k)

    valid.sort(key=new_key)
    if ctx.gene_type in valid:
        valid.remove(ctx.gene_type)
        valid.insert(0, ctx.gene_type)

    actions.extend(("new", k) for k in valid)
    return actions
```

The rule uses a maintenance-aware earliest-deadline-first bias, but balances a combined load of duty hours and duty counts (normalized by the average work time) rather than only hours. The balance weight is adapted to capacity slack: when capacity is plentiful, load balancing dominates; when tight, urgency dominates. For new-robot type selection, it estimates the steady-state number of robots needed by including travel/charge recovery and maintenance downtime, preferring types that can cover the remaining horizon with fewer resources.

```python
def rule(ctx):
    available = ctx.available
    actions = []

    # Combined load: average of duty hours and count scaled by average work time.
    total_hours = 0.0
    total_count = 0
    for r in ctx.robots:
        total_hours += r.hours
        total_count += r.count
    if total_count > 0:
        avg_wt = total_hours / total_count
    else:
        avg_wt = 10.0

    def rem_h(r):
        return r.duties_left * ctx.types[r.type]['work_time']

    def load(r):
        return (r.hours + r.count * avg_wt) * 0.5

    def recovery(r):
        t = ctx.types[r.type]
        return t['out_travel_time'] + t['return_travel_time'] + t['charge_time']

    # Adaptive balance weight from capacity slack.
    capacity = ctx.capacity
    slack = capacity - ctx.remaining
    if ctx.remaining > 0:
        alpha = slack / ctx.remaining
        if alpha < 0.0:
            alpha = 0.0
        elif alpha > 1.0:
            alpha = 1.0
    else:
        alpha = 1.0

    def score(r):
        return rem_h(r) + alpha * load(r)

    unmaintained = [r for r in available if r.first_maint is None]
    maintained = [r for r in available if r.first_maint is not None]

    # Sort by score, then shorter recovery, then count, hours, idx.
    unmaintained.sort(key=lambda r: (score(r), recovery(r), r.count, r.hours, r.idx))
    maintained.sort(key=lambda r: (score(r), recovery(r), r.count, r.hours, r.idx))

    for r in unmaintained:
        actions.append(("reuse", r))
    for r in maintained:
        actions.append(("reuse", r))

    # New robot type preference: estimate steady-state robots needed.
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)

    if valid:
        opened_types = set()
        for r in ctx.robots:
            opened_types.add(r.type)

        def new_key(k):
            t = ctx.types[k]
            wt = t['work_time']
            rec = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
            swt = t['single_work_time']
            cmw = t['continue_max_work']
            mt = t['maintenance_time']
            duties_per_cycle = cmw // swt if swt > 0 else 0
            work_hours = duties_per_cycle * wt
            if work_hours > 0:
                required = (work_hours + duties_per_cycle * rec + mt) / work_hours
            else:
                required = 1e9
            fits = 0 if wt <= ctx.remaining else 1
            existing = 1 if k in opened_types else 0
            if fits == 0:
                wt_pref = -wt
            else:
                wt_pref = wt
            return (fits, -existing, required, mt, -cmw, wt_pref, k)

        valid.sort(key=new_key)
        if ctx.gene_type in valid:
            valid.remove(ctx.gene_type)
            valid.insert(0, ctx.gene_type)

        actions.extend(("new", k) for k in valid)

    return actions
