        t = ctx.types[k]
        if t is not None:
            work_times.append(t['work_time'])
    work_times = list(set(work_times))
    g = 0
    for wt in work_times:
        g = math.gcd(g, wt)
    max_check = 100
    dp = [False] * (max_check + 1)
    dp[0] = True
    for i in range(max_check + 1):
        if dp[i]:
            for wt in work_times:
                if i + wt <= max_check:
                    dp[i + wt] = True

    def is_rep(x):
        if x < 0:
            return False
        if x % g != 0:
            return False
        if x > max_check:
            return True
        return dp[x]

    # --- Load metrics ---
    total_hours = 0.0
    total_count = 0
    for r in ctx.robots:
        total_hours += r.hours
        total_count += r.count
    avg_wt = total_hours / total_count if total_count > 0 else 10.0

    capacity = ctx.capacity
    slack = capacity - R
    if R > 0:
        alpha = slack / R
        if alpha < 0.0: alpha = 0.0
        elif alpha > 1.0: alpha = 1.0
    else:
        alpha = 1.0

    def load(r):
        return (r.hours + r.count * avg_wt) * 0.5

    def rem_h(r):
        return r.duties_left * ctx.types[r.type]['work_time']

    def fit_penalty(r):
        wt = ctx.types[r.type]['work_time']
        if wt > R:
            return 10000
        R2 = R - wt
        if R2 == 0:
            return -1000
        if not is_rep(R2):
            return 1000
        return 0

    def comb_score(r):
        return rem_h(r) + alpha * load(r) + fit_penalty(r)

    def bal_score(r):
        return load(r)

    # --- Split feasible / infeasible ---
    feasible = []
    infeasible = []
    for r in available:
        if fit_penalty(r) >= 1000:
            infeasible.append(r)
        else:
            feasible.append(r)

    feasible_comb = sorted(feasible, key=lambda r: (comb_score(r), r.count, r.hours, r.idx))
    feasible_bal  = sorted(feasible, key=lambda r: (bal_score(r), r.count, r.hours, r.idx))

