    actions = []
    added = set()
    i = 0
    j = 0
    if feasible_comb:
        r = feasible_comb[0]
        actions.append(("reuse", r))
        added.add(r.idx)
        i = 1

    while i < len(feasible_comb) or j < len(feasible_bal):
        while j < len(feasible_bal) and feasible_bal[j].idx in added:
            j += 1
        if j < len(feasible_bal):
            r = feasible_bal[j]
            actions.append(("reuse", r))
            added.add(r.idx)
            j += 1

        while i < len(feasible_comb) and feasible_comb[i].idx in added:
            i += 1
        if i < len(feasible_comb):
            r = feasible_comb[i]
            actions.append(("reuse", r))
            added.add(r.idx)
            i += 1

    infeasible.sort(key=lambda r: (comb_score(r), r.count, r.hours, r.idx))
    for r in infeasible:
        if r.idx not in added:
            actions.append(("reuse", r))

    # --- New robot type ordering (used when no robot is available) ---
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)

