    u_infeas.sort(key=lambda r: (comb_score(r), recovery(r), r.count, r.hours, r.idx))
    m_infeas.sort(key=lambda r: (comb_score(r), recovery(r), r.count, r.hours, r.idx))
    for r in u_infeas:
        actions.append(("reuse", r))
    for r in m_infeas:
        actions.append(("reuse", r))

    # New robot type preference
    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)

    if valid:
        opened_types = set(r.type for r in ctx.robots)

        def new_key(k):
            t = ctx.types[k]
            wt = t['work_time']
            swt = t['single_work_time']
            cmw = t['continue_max_work']
            mt = t['maintenance_time']
            out_t = t['out_travel_time']
            ret_t = t['return_travel_time']
            ch_t = t['charge_time']

            duties_per_cycle = cmw // swt if swt > 0 else 0
            work_hours = duties_per_cycle * wt
            if work_hours > 0:
                required = (work_hours + duties_per_cycle * (out_t + ret_t + ch_t) + mt) / work_hours
            else:
                required = 1e9

            if wt > R:
                bad_fit = 2
                exact = 0
                wt_pref = wt
            else:
                R2 = R - wt
                if R2 == 0:
                    exact = 1
                    bad_fit = 0
                elif not is_rep(R2):
                    exact = 0
                    bad_fit = 1
                else:
                    exact = 0
                    bad_fit = 0
                wt_pref = -wt

            existing = 1 if k in opened_types else 0
            return (bad_fit, -exact, -existing, required, mt, -cmw, wt_pref, k)

        valid.sort(key=new_key)
        if ctx.gene_type in valid:
            valid.remove(ctx.gene_type)
            valid.insert(0, ctx.gene_type)

        for k in valid:
            actions.append(("new", k))

    return actions
