The key idea is to adaptively trade off **balance** (synchronising maintenance to keep counts, hours, and first-maintenance times similar) against **staggering** (deliberately unbalancing robots to avoid simultaneous maintenance gaps). I use `ctx.capacity` slack to decide: when there is plenty of spare capacity, I keep all robots at nearly equal load and prefer robots with more remaining budget (to delay maintenance and synchronise first-maintenance times). When capacity is tight, I allow a controlled load window and prefer robots closer to maintenance, so they go for maintenance early while others keep working. Near the end of the horizon I switch back to strict balance and avoid triggering maintenance.

```python
def rule(ctx):
    available = ctx.available
    actions = []

    total_hours = 0.0
    total_count = 0
    for r in ctx.robots:
        total_hours += r.hours
        total_count += r.count
    if total_count > 0:
        avg_wt = total_hours / total_count
    else:
        avg_wt = 10.0

    remaining = ctx.remaining
    capacity = ctx.capacity
    if capacity > 0 and remaining > 0:
        slack_ratio = (capacity - remaining) / remaining
    else:
        slack_ratio = 0.0

    # Decide whether to stagger maintenance or keep strict balance.
    if remaining < 100.0:
        stagger = False
        K = 0
    else:
        if slack_ratio >= 0.4:
            stagger = False
            K = 0
        elif slack_ratio >= 0.2:
            stagger = True
            K = 1
        elif slack_ratio >= 0.0:
            stagger = True
            K = 2
        else:
            stagger = True
            K = 3

    def rem_budget(r):
        return r.duties_left * ctx.types[r.type]['work_time']

    def load(r):
        return r.hours + r.count * avg_wt

    def recovery(r):
        t = ctx.types[r.type]
        return t['out_travel_time'] + t['return_travel_time'] + t['charge_time']

    if available:
        min_load = min(load(r) for r in available)
        threshold = min_load + K * avg_wt + 1e-9

        if stagger:
            def sort_key(r):
                in_window = 0 if load(r) <= threshold else 1
                return (in_window, rem_budget(r), load(r), recovery(r), r.count, r.hours, r.idx)
        else:
            def sort_key(r):
                in_window = 0 if load(r) <= threshold else 1
                return (in_window, -rem_budget(r), load(r), recovery(r), r.count, r.hours, r.idx)

        available_sorted = sorted(available, key=sort_key)
        for r in available_sorted:
            actions.append(("reuse", r))

    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)

    if valid:
        opened_types = set()
        for r in ctx.robots:
            opened_types.add(r.type)

        def new_key(k):
            t = ctx.types[k]
            wt = t['work_time']
            rec = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
            swt = t['single_work_time']
            cmw = t['continue_max_work']
            mt = t['maintenance_time']
            duties_per_cycle = cmw // swt if swt > 0 else 1
            work_hours = duties_per_cycle * wt
            if work_hours > 0:
                required = (work_hours + duties_per_cycle * rec + mt) / work_hours
            else:
                required = 1e9
            fits = 0 if wt <= remaining else 1
            existing = 1 if k in opened_types else 0
            wt_pref = -wt if fits == 0 else wt
            return (fits, -existing, required, mt, -cmw, wt_pref, k)

        valid.sort(key=new_key)
        if ctx.gene_type in valid:
            valid.remove(ctx.gene_type)
            valid.insert(0, ctx.gene_type)

        actions.extend(("new", k) for k in valid)

    return actions
