The improved rule adds endgame awareness to avoid leaving uncoverable remainders, and replaces the new-robot type selection with a resource-aware estimate that weighs the tool cost of opening a new type against the number of additional robots required, using the remaining shortfall and the total duty hours a robot can supply before the horizon. It also ensures that any available robot can actually fit the remaining horizon before selecting it.

```python
def rule(ctx):
    def rem_h(r):
        return r.duties_left * ctx.types[r.type]['work_time']

    capacity = ctx.capacity
    slack = capacity - ctx.remaining
    if ctx.remaining > 0:
        alpha = slack / ctx.remaining
        if alpha < 0.0:
            alpha = 0.0
        elif alpha > 1.0:
            alpha = 1.0
    else:
        alpha = 1.0

    available_types = set(r.type for r in ctx.available)
    min_wt = float('inf')
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and (ctx.left[k] > 0 or k in available_types):
            wt = t['work_time']
            if wt < min_wt:
                min_wt = wt
    if min_wt == float('inf'):
        min_wt = 1.0

    def fits_robot(r):
        return 0 if ctx.types[r.type]['work_time'] <= ctx.remaining else 1

    def bad_end(r):
        wt = ctx.types[r.type]['work_time']
        rem_after = ctx.remaining - wt
        if 0 < rem_after < min_wt:
            return 1
        return 0

    def score(r):
        return rem_h(r) + alpha * r.hours

    unmaintained = [r for r in ctx.available if r.first_maint is None]
    maintained = [r for r in ctx.available if r.first_maint is not None]

    unmaintained.sort(key=lambda r: (fits_robot(r), bad_end(r), score(r), r.count, r.idx))
    maintained.sort(key=lambda r: (fits_robot(r), bad_end(r), score(r), r.count, r.idx))

    actions = []
    for r in unmaintained:
        actions.append(("reuse", r))
    for r in maintained:
        actions.append(("reuse", r))

    valid = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None and ctx.left[k] > 0:
            valid.append(k)

    if valid:
        opened_types = set()
        for r in ctx.robots:
            opened_types.add(r.type)

        def total_duty_hours(k):
            t = ctx.types[k]
            wt = t['work_time']
            out = t['out_travel_time']
            ret = t['return_travel_time']
            ch = t['charge_time']
            swt = t['single_work_time']
            cmw = t['continue_max_work']
            mt = t['maintenance_time']
            C = wt + out + ret + ch
            if C <= 0 or wt <= 0:
                return 0.0
            D = cmw // swt if swt > 0 else 1
            if D <= 0:
                D = 1
            T_cycle = D * C + mt
            R = ctx.remaining
            if R <= 0:
                return 0.0
            full = int(R // T_cycle)
            rem = R - full * T_cycle
            total = full * D * wt
            if rem >= wt:
                n = int((rem - wt) // C) + 1
                if n > D:
                    n = D
                total += n * wt
            return total

        def new_key(k):
            t = ctx.types[k]
            wt = t['work_time']
            total = total_duty_hours(k)
            if total <= 0:
                total = 1.0
            R_rem = ctx.remaining - ctx.capacity
            if R_rem <= 0:
                R_rem = 1.0
            n_robots = int((R_rem + total - 1) / total)
            existing = 1 if k in opened_types else 0
            tool_cost = 1 - existing
            total_res = n_robots + tool_cost
            fits = 0 if wt <= ctx.remaining else 1
            return (fits, total_res, -total, t['maintenance_time'], -t['continue_max_work'], k)

        valid.sort(key=new_key)

        if ctx.gene_type in valid:
            valid.remove(ctx.gene_type)
            valid.insert(0, ctx.gene_type)

        actions.extend(("new", k) for k in valid)

    return actions
