        alpha = (cap - R) / R
        if alpha < 0.0:
            alpha = 0.0
        elif alpha > 1.0:
            alpha = 1.0
    else:
        alpha = 1.0

    tot_h = 0.0
    tot_c = 0
    for r in ctx.robots:
        tot_h += r.hours
        tot_c += r.count
    if tot_c > 0:
        avg_wt = tot_h / tot_c
    elif wts:
        avg_wt = sum(wts) / len(wts)
    else:
        avg_wt = 10.0

    def recov(r):
        t = types[r.type]
        return t['out_travel_time'] + t['return_travel_time'] + t['charge_time']

    def key_flush(r):
        t = types[r.type]
        urg = r.duties_left * (t['work_time'] + recov(r))
        ld = r.hours + r.count * avg_wt
        return (fit_pen(r), urg + alpha * ld, recov(r), r.count, r.idx)

    def key_bal(r):
        t = types[r.type]
        s = r.duties_left * t['work_time'] + alpha * r.hours
        return (fit_pen(r), s, r.count, r.hours, r.idx)

    def interleave(a, b):
        out = []
        seen = set()
        la = len(a)
        lb = len(b)
