The combined rule merges Rule 2’s feasibility-aware logic (representable remainders, exact-finish bonus, new-robot efficiency key) with Rule 1’s simple load/remaining-work bias. For feasible available robots, it interleaves three sorted orders: Rule 2’s combined urgency/load score, a pure load-balancing score, and Rule 1’s remaining-work-plus-hours score. Infeasible robots are placed last as fallbacks. This yields a strong default choice and a diverse, useful ordering of reuse alternatives for the evolutionary search, while keeping the new-robot type preference from Rule 2.

```python
def rule(ctx):
    R = ctx.remaining

    # ---- representable remainders: gcd + small DP over work-times ----
    work_times = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is not None:
            work_times.append(t['work_time'])
    work_times = list(set(work_times))

    g = 0
    for wt in work_times:
        g = math.gcd(g, wt)

    max_check = 200
    dp = [False] * (max_check + 1)
    dp[0] = True
    for i in range(max_check + 1):
        if dp[i]:
            for wt in work_times:
                j = i + wt
                if j <= max_check:
                    dp[j] = True

    def is_rep(x):
        if x < 0:
            return False
        if g > 0 and x % g != 0:
            return False
        if x > max_check:
            return True
        return dp[x]

    # ---- load-balancing statistics ----
    total_hours = 0.0
    total_count = 0
    for r in ctx.robots:
        total_hours += r.hours
        total_count += r.count
    avg_wt = total_hours / total_count if total_count > 0 else 10.0

    capacity = ctx.capacity
    slack = capacity - R
    if R > 0:
        alpha = slack / R
        if alpha < 0.0:
            alpha = 0.0
        elif alpha > 1.0:
            alpha = 1.0
    else:
        alpha = 1.0

    def load(r):
        return r.hours + r.count * avg_wt

    def urgency(r):
        t = ctx.types[r.type]
        cycle = t['work_time'] + t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        return r.duties_left * cycle

    def recovery(r):
        t = ctx.types[r.type]
        return t['out_travel_time'] + t['return_travel_time'] + t['charge_time']

    def rem_h(r):
        return r.duties_left * ctx.types[r.type]['work_time']

    def fit_penalty(r):
        wt = ctx.types[r.type]['work_time']
        if wt > R:
            return 10000
        R2 = R - wt
        if R2 == 0:
            return -1000
        if not is_rep(R2):
            return 1000
        return 0

    def comb_score(r):
        return (fit_penalty(r), urgency(r) + alpha * load(r))

    def bal_score(r):
        return (fit_penalty(r), load(r))

    def rule1_score(r):
        return (fit_penalty(r), rem_h(r) + alpha * r.hours)

    avail = ctx.available
    unmaintained = [r for r in avail if r.first_maint is None]
    maintained = [r for r in avail if r.first_maint is not None]

    def split_feasible(group):
        feas = []
        infeas = []
        for r in group:
            if fit_penalty(r) < 1000:
                feas.append(r)
            else:
                infeas.append(r)
        return feas, infeas

    u_feas, u_infeas = split_feasible(unmaintained)
    m_feas, m_infeas = split_feasible(maintained)

    def order_lists(feas):
        comb = sorted(feas, key=lambda r: (comb_score(r), recovery(r), r.count, r.hours, r.idx))
        bal = sorted(feas, key=lambda r: (bal_score(r), recovery(r), r.count, r.hours, r.idx))
        rule1 = sorted(feas, key=lambda r: (rule1_score(r), recovery(r), r.count, r.hours, r.idx))
        return comb, bal, rule1

    u_comb, u_bal, u_rule1 = order_lists(u_feas)
    m_comb, m_bal, m_rule1 = order_lists(m_feas)

    def interleave(lists):
        out = []
        seen = set()
        idx = [0] * len(lists)
        unique = set()
        for l in lists:
            for r in l:
                unique.add(r.idx)
        unique_count = len(unique)
        sum_len = sum(len(l) for l in lists)
        for _ in range(sum_len * len(lists) + 1):
